package com.dunerealms.quests;
import com.example.dunerealms.SafeWormPlacement;
import com.example.dunerealms.WormBridge;
import com.example.dunegui.NativeMenus;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.event.ClickEvent;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.world.ChunkLoadEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Server-authoritative hidden encounter engine. No currency writes or fabricated completion. */
public final class DuneQuests extends JavaPlugin implements Listener,CommandExecutor {
 private final ExecutorService worker=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"DuneQuests-storage");t.setDaemon(true);return t;});
 private final AtomicBoolean dueBusy=new AtomicBoolean(),activeBusy=new AtomicBoolean();
 private volatile QuestStore store;private volatile boolean ready;private JavaPlugin core;private String serverId;
 private NamespacedKey eventKey,playerKey,expiryKey;private final Set<UUID> assigned=new HashSet<>();
 static boolean validServer(String id){return id!=null&&Set.of("arrakis","kaitain","giedi_prime","caladan","sigma_draconis_iv","lobby").contains(id);}
 @Override public void onEnable(){saveDefaultConfig();serverId=getConfig().getString("server-id","arrakis");if(!validServer(serverId))throw new IllegalStateException("Invalid fixed server-id");core=(JavaPlugin)getServer().getPluginManager().getPlugin("DuneCore");eventKey=new NamespacedKey(this,"event");playerKey=new NamespacedKey(this,"player");expiryKey=new NamespacedKey(this,"expiry");getServer().getPluginManager().registerEvents(this,this);getCommand("dunequests").setExecutor(this);
  var own=getConfig();String url=own.getString("database.jdbc-url","");if(url.isBlank()){url=core.getConfig().getString("database.jdbc-url","");own.set("database.username",core.getConfig().getString("database.username",""));own.set("database.password",core.getConfig().getString("database.password",""));}
  try{store=new QuestStore(url,own.getString("database.username",""),own.getString("database.password",""));worker.execute(()->{try{store.initialize();ready=true;getLogger().info("Authoritative MySQL quest engine ready; hidden definitions remain private.");}catch(Exception e){getLogger().severe("Quest storage unavailable. No encounter or reward will be invented.");}});}catch(Exception e){getLogger().severe("Private MySQL quest settings required. Engine remains disabled.");}
  getServer().getScheduler().runTaskTimer(this,this::hourly,200,600);getServer().getScheduler().runTaskTimer(this,this::monitor,100,40);
 }
 @Override public void onDisable(){ready=false;worker.shutdownNow();}
 private void main(Runnable action){if(isEnabled())getServer().getScheduler().runTask(this,action);}
 static boolean engineHost(String serverId,World world){return "arrakis".equals(serverId)&&world!=null&&world.getName().equalsIgnoreCase("arrakis");}
 private void hourly(){World world=getServer().getWorld("arrakis");if(!ready||!engineHost(serverId,world)||!dueBusy.compareAndSet(false,true))return;List<Player> eligible=new ArrayList<>(world.getPlayers().stream().filter(SafeWormPlacement::eligible).filter(p->!assigned.contains(p.getUniqueId())).toList());Player chosen=eligible.isEmpty()?null:eligible.get(java.util.concurrent.ThreadLocalRandom.current().nextInt(eligible.size()));boolean cap=WormBridge.count(core)>=2;UUID player=chosen==null||cap?null:chosen.getUniqueId();String reason=cap?"Two-worm hard limit occupied":"No eligible online Arrakis survival player";
  worker.execute(()->{try{QuestStore.Attempt attempt=store.claimDue(player,reason);if(attempt!=null&&attempt.player()!=null)main(()->prepare(attempt));}catch(Exception e){getLogger().warning("Quest scheduling could not be verified; no encounter started.");}finally{dueBusy.set(false);}});
 }
 private void prepare(QuestStore.Attempt attempt){Player target=getServer().getPlayer(attempt.player());if(!SafeWormPlacement.eligible(target)||WormBridge.count(core)>=2){finish(attempt.id(),null,"skipped","Target eligibility changed or worm cap occupied",null);return;}Location at=SafeWormPlacement.find(target,java.util.concurrent.ThreadLocalRandom.current());if(at==null){finish(attempt.id(),null,"skipped","No safe unclaimed dry placement 48–80 blocks away",null);return;}final UUID worm;
  try{worm=WormBridge.encounter(core,target,at);Entity body=getServer().getEntity(worm);if(body==null)throw new IllegalStateException();body.getPersistentDataContainer().set(eventKey,PersistentDataType.STRING,attempt.id().toString());body.getPersistentDataContainer().set(playerKey,PersistentDataType.STRING,attempt.player().toString());body.getPersistentDataContainer().set(expiryKey,PersistentDataType.LONG,System.currentTimeMillis()+attempt.definition().survive()*1000L+120000);assigned.add(attempt.player());}catch(Exception failure){finish(attempt.id(),null,"skipped","Core refused unsafe placement or occupied cap",null);return;}
  worker.execute(()->{try{QuestStore.Event event=store.assign(attempt,worm);main(()->{Player current=getServer().getPlayer(attempt.player());if(!SafeWormPlacement.eligible(current)){finish(event.id(),worm,"failed","Player left the eligible encounter",attempt.player());return;}current.sendMessage(Component.text("Quest discovered: "+event.title()+". Survive "+attempt.definition().survive()+" seconds or defeat the worm. This encounter has no additional Dunemark payout."));});}catch(Exception e){main(()->WormBridge.retire(core,worm));finish(attempt.id(),null,"failed","Assignment could not be confirmed",attempt.player());}});
 }
 private void monitor(){World world=getServer().getWorld("arrakis");if(!ready||!engineHost(serverId,world)||!activeBusy.compareAndSet(false,true))return;worker.execute(()->{try{QuestStore.Active state=store.active();main(()->{assigned.clear();for(QuestStore.Event event:state.events()){
   if(event.status().equals("preparing")){if(QuestRules.outcome(event,true,state.now()).equals("failed"))finish(event.id(),event.worm(),"failed","Encounter preparation interrupted",event.player());continue;}
   Player player=event.player()==null?null:getServer().getPlayer(event.player());if(!SafeWormPlacement.eligible(player)){finish(event.id(),event.worm(),"failed","Player died, left Arrakis or entered a protected area",event.player());continue;}assigned.add(event.player());if(QuestRules.outcome(event,true,state.now()).equals("completed"))finish(event.id(),event.worm(),"completed","Survived the authoritative encounter duration",event.player());
  }});}catch(Exception e){/* No completion or reward is asserted during a database outage. */}finally{activeBusy.set(false);}});}
 private void finish(UUID event,UUID worm,String status,String reason,UUID player){worker.execute(()->{boolean changed=false;try{changed=store.finish(event,status,reason);}catch(Exception e){getLogger().warning("Quest outcome could not be saved; no payout or success asserted.");}boolean confirmed=changed;main(()->{if(worm!=null)WormBridge.retire(core,worm);if(player!=null)assigned.remove(player);Player owner=player==null?null:getServer().getPlayer(player);if(confirmed&&owner!=null&&status.equals("completed"))owner.sendMessage(Component.text("Quest completed. No additional Dunemark reward is configured."));});});}
 @EventHandler(priority=EventPriority.MONITOR)public void wormDeath(EntityDeathEvent event){String id=event.getEntity().getPersistentDataContainer().get(eventKey,PersistentDataType.STRING),player=event.getEntity().getPersistentDataContainer().get(playerKey,PersistentDataType.STRING);if(id==null||player==null)return;try{UUID owner=UUID.fromString(player);Player current=getServer().getPlayer(owner);finish(UUID.fromString(id),null,QuestRules.defeated(SafeWormPlacement.eligible(current)),SafeWormPlacement.eligible(current)?"Encounter worm defeated":"Player was no longer eligible",owner);}catch(IllegalArgumentException ignored){}}
 @EventHandler public void chunkLoaded(ChunkLoadEvent event){if(!event.getWorld().getName().equalsIgnoreCase("arrakis"))return;for(Entity entity:event.getChunk().getEntities()){Long expiry=entity.getPersistentDataContainer().get(expiryKey,PersistentDataType.LONG);if(expiry!=null&&expiry<System.currentTimeMillis())WormBridge.retire(core,entity.getUniqueId());}}
 private Inventory loading(Player player,String title,boolean admin){Inventory model=getServer().createInventory(null,27,title);NativeMenus.inventory(this,player,title,model,Map.of(22,()->player.closeInventory()),()->player.isOnline()&&player.hasPermission(admin?"dune.quests.admin":"dune.quests.view"));return model;}
 private boolean current(Player p,UUID owner,Inventory model,boolean admin){return p.isOnline()&&p.getUniqueId().equals(owner)&&p.hasPermission(admin?"dune.quests.admin":"dune.quests.view")&&NativeMenus.isCurrent(p,model);}
 private void own(Player player){if(!ready||!player.hasPermission("dune.quests.view")){player.sendMessage("Quest records are unavailable or permission is missing.");return;}Inventory model=loading(player,"Discoveries · Loading",false);UUID owner=player.getUniqueId();worker.execute(()->{try{List<QuestStore.Event> rows=store.player(owner);main(()->{if(!current(player,owner,model,false))return;List<NativeMenus.Choice> choices=new ArrayList<>();for(QuestStore.Event event:rows)choices.add(new NativeMenus.Choice(event.title()+" · "+event.status(),event.description(),()->{if(player.isOnline()&&player.hasPermission("dune.quests.view"))NativeMenus.show(this,player,event.title(),event.description()+"\nStatus: "+event.status()+"\nNo additional Dunemark payout is configured.",List.of(new NativeMenus.Choice("Back","Your discovered quests",()->own(player))));}));if(choices.isEmpty())choices.add(new NativeMenus.Choice("No discoveries yet","Quest opportunities are uncovered while playing.",()->{}));NativeMenus.show(this,player,"Your Discoveries","Only quests assigned to or discovered by your Minecraft UUID appear here.",choices);});}catch(Exception unavailable){main(()->{if(current(player,owner,model,false))player.sendMessage("Quest history could not be verified. Try again shortly.");});}});}
 private void admin(Player player){if(!ready||!player.hasPermission("dune.quests.admin")){player.sendMessage("Current dune.quests.admin permission is required.");return;}Inventory model=loading(player,"Quest Engine · Loading",true);UUID owner=player.getUniqueId();worker.execute(()->{try{List<QuestStore.Definition> definitions=store.definitions();main(()->{if(!current(player,owner,model,true))return;List<NativeMenus.Choice> choices=new ArrayList<>();for(QuestStore.Definition d:definitions)choices.add(new NativeMenus.Choice(d.title(),"Hidden: "+d.hidden()+" · interval "+d.interval()+"s · survival "+d.survive()+"s · version "+d.version(),()->{if(player.hasPermission("dune.quests.admin"))player.sendMessage(Component.text("Open authoritative quest administration →").clickEvent(ClickEvent.openUrl("https://cp.dunerealms.com/#quests")));}));NativeMenus.show(this,player,"Quest Administration","Worm cap: two, fixed. No additional Dunemark rewards. Configuration is versioned in the website control panel.",choices);});}catch(Exception unavailable){main(()->player.sendMessage("Quest engine configuration is unavailable."));}});}
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player player)){sender.sendMessage("Open the authenticated website quest administration panel.");return true;}if(args.length==1&&args[0].equalsIgnoreCase("admin"))admin(player);else own(player);return true;}
}

